# This code has been fully generated by an AI.
"""Green-Screen-Memes werden sauber freigestellt und ersetzen das Original erst nach geprüftem Ergebnis."""

import av
import numpy as np
import pytest

from hebocon.memes import KeyingError, convert, cutout, has_alpha, key_color, process_file, process_folder

GREEN = (20, 230, 30)  # BGR


def green_frame(w=64, h=48, color=GREEN):
    img = np.zeros((h, w, 3), np.uint8)
    img[:] = color
    img[16:32, 24:40] = (40, 40, 220)
    return img


def test_green_becomes_transparent_and_content_stays():
    img = green_frame()
    # Kantenpixel zu drei Vierteln Grün, wie nach einer Verkleinerung.
    img[16:32, 23] = (np.array(GREEN) * 3 + (40, 40, 220)) // 4
    rgb, alpha = cutout(img, key_color(img))
    assert alpha[0, 0] == 0 and alpha[24, 32] == 1
    # Die Kante wird eingezogen und läuft weich aus, statt hart abzubrechen.
    assert alpha[24, 23] == 0 and 0 < alpha[24, 26] < 1
    # Kein Grünschimmer an der Kante.
    assert rgb[24, 26, 1] <= max(rgb[24, 26, 0], rgb[24, 26, 2])


def write_clip(path, frames=12, color=GREEN):
    with av.open(str(path), "w") as out:
        video = out.add_stream("libx264", rate=24)
        video.width, video.height, video.pix_fmt = 64, 48, "yuv420p"
        audio = out.add_stream("aac", rate=44100)
        for i in range(frames):
            out.mux(video.encode(av.VideoFrame.from_ndarray(green_frame(color=color), format="bgr24")))
            samples = np.zeros((1, 1024), np.float32)
            frame = av.AudioFrame.from_ndarray(samples, format="fltp", layout="mono")
            frame.sample_rate, frame.pts = 44100, i * 1024
            out.mux(audio.encode(frame))
        out.mux(video.encode(None))
        out.mux(audio.encode(None))


def decoded(path):
    with av.open(str(path)) as result:
        kinds = {s.type: s.codec_context.name for s in result.streams}
        decoder = av.CodecContext.create("libvpx-vp9", "r")
        frames = [f for p in result.demux(result.streams.video[0]) for f in decoder.decode(p)]
    return kinds, frames


def test_convert_writes_vp9_with_alpha_and_sound(tmp_path):
    src, dst = tmp_path / "Meme_001.mp4", tmp_path / "out.webm"
    write_clip(src)
    convert(src, dst, key_color(green_frame()))
    kinds, frames = decoded(dst)
    assert kinds == {"video": "vp9", "audio": "opus"}
    assert frames and frames[0].format.name == "yuva420p"
    # Auf den sichtbaren Inhalt zugeschnitten statt des ganzen grünen Bilds.
    assert frames[0].width < 64 and frames[0].height < 48
    bgra = frames[0].to_ndarray(format="bgra")
    assert bgra[0, 0, 3] < 30 and bgra[bgra.shape[0] // 2, bgra.shape[1] // 2, 3] > 220
    assert has_alpha(dst)


def test_process_file_replaces_original_only_with_checked_result(tmp_path):
    src = tmp_path / "Meme_001.mp4"
    write_clip(src)
    out = process_file(src)
    assert out == tmp_path / "Meme_001.webm" and has_alpha(out)
    assert not src.exists()
    assert sorted(p.name for p in tmp_path.iterdir()) == ["Meme_001.webm"]
    # Ein zweiter Lauf fasst das fertige Ergebnis nicht noch einmal an.
    stamp = out.stat().st_mtime_ns
    assert process_file(out) == out and out.stat().st_mtime_ns == stamp


def test_video_without_green_screen_stays_untouched(tmp_path):
    src = tmp_path / "Katze.mp4"
    write_clip(src, color=(90, 90, 90))
    assert process_file(src) is None
    assert sorted(p.name for p in tmp_path.iterdir()) == ["Katze.mp4"]


def test_failed_conversion_keeps_original(tmp_path, monkeypatch):
    src = tmp_path / "Meme_002.mp4"
    write_clip(src)

    def broken(*_args, **_kwargs):
        raise KeyingError("kaputt")

    monkeypatch.setattr("hebocon.memes.validate", broken)
    with pytest.raises(KeyingError):
        process_file(src)
    assert sorted(p.name for p in tmp_path.iterdir()) == ["Meme_002.mp4"]


def test_folder_run_processes_each_video_once(tmp_path):
    write_clip(tmp_path / "Meme_001.mp4")
    write_clip(tmp_path / "grau.mp4", color=(90, 90, 90))
    (tmp_path / "sound.mp3").write_bytes(b"kein Video")
    assert process_folder(tmp_path, workers=1) == (1, 1, 0)
    assert sorted(p.name for p in tmp_path.iterdir()) == ["Meme_001.webm", "grau.mp4", "sound.mp3"]
    assert process_folder(tmp_path, workers=1) == (0, 2, 0)
